def group_by(items, key):
    """Group a list of dictionaries by the value of a given key."""
    groups = {}
    for item in items:
        group_key = item[key]
        groups.setdefault(group_key, []).append(item)
    return groups


if __name__ == "__main__":
    import unittest

    class TestGroupBy(unittest.TestCase):
        def test_basic_grouping(self):
            data = [
                {"dept": "eng", "name": "Alice"},
                {"dept": "eng", "name": "Bob"},
                {"dept": "hr", "name": "Carol"},
            ]
            result = group_by(data, "dept")
            self.assertEqual(list(result.keys()), ["eng", "hr"])
            self.assertEqual(len(result["eng"]), 2)
            self.assertEqual(len(result["hr"]), 1)

        def test_empty_list(self):
            self.assertEqual(group_by([], "key"), {})

        def test_single_item(self):
            data = [{"type": "a", "val": 1}]
            result = group_by(data, "type")
            self.assertEqual(result, {"a": [{"type": "a", "val": 1}]})

        def test_missing_key_raises(self):
            with self.assertRaises(KeyError):
                group_by([{"a": 1}], "b")

        def test_numeric_key(self):
            data = [{"id": 1, "x": "a"}, {"id": 2, "x": "b"}, {"id": 1, "x": "c"}]
            result = group_by(data, "id")
            self.assertEqual(len(result[1]), 2)
            self.assertEqual(len(result[2]), 1)

    unittest.main()
